#!/usr/bin/env bash
#
# Reclaim disk from build artifacts cargo never garbage-collects.
#
# Cargo mints a fresh `target/debug/build/<pkg>-<hash>/` directory every time a
# build script's inputs change, and never removes the previous one. For this
# workspace that matters a lot: athena-voice-runtime's build script emits the
# compiled whisper.cpp tree into `out/`, ~470 MB a copy. Fourteen of those had
# piled up over four days of ordinary work.
#
# Nothing here is load-bearing. Every directory this deletes is regenerated by
# the next `cargo build` — the only cost of over-deleting is rebuild time, never
# a broken tree.
#
# That margin matters, because "newest" is not the same as "live". Cargo does
# not touch a build directory it reuses unchanged, so a hash that is current for
# one feature set can look older than hashes minted by intervening builds of a
# different one — this repo builds several (native, docker, voice, assist).
# Pruning by age therefore drops the configs you have not built lately, which is
# the right instinct for reclaiming disk, but it will occasionally cost one
# whisper.cpp rebuild (~90 s) the next time you return to such a config. Keeping
# a few generations per package buys that back cheaply; --keep 1 trades it away.
#
# Usage:
#   scripts/clean-stale.sh              # stale build-hash dirs + incremental cache
#   scripts/clean-stale.sh -n           # dry run: report, delete nothing
#   scripts/clean-stale.sh --keep 1     # keep only the newest generation (frees more)
#   scripts/clean-stale.sh --esp32      # also wipe satellite-esp32/target (~2.7 GB)
#   scripts/clean-stale.sh --sdd        # also drop finished review scratch in .superpowers/sdd
#   scripts/clean-stale.sh --all        # everything above
#
# Never touched: models/ (downloaded whisper + piper weights), whisper.cpp/,
# satellite-esp32/.embuild/ (the ESP-IDF toolchain, expensive to re-fetch), and
# anything git tracks.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

KEEP=3
DRY_RUN=0
DO_ESP32=0
DO_SDD=0
SDD_AGE_DAYS=14

TAB=$'\t'
RECLAIMED_KB=0

die() { printf 'clean-stale: %s\n' "$1" >&2; exit 2; }

while [ $# -gt 0 ]; do
    case "$1" in
        -n|--dry-run) DRY_RUN=1 ;;
        --keep)       KEEP="${2:-}"; shift
                      case "$KEEP" in ''|*[!0-9]*) die "--keep needs a number" ;; esac ;;
        --esp32)      DO_ESP32=1 ;;
        --sdd)        DO_SDD=1 ;;
        --all)        DO_ESP32=1; DO_SDD=1 ;;
        -h|--help)    sed -n '3,30p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'; exit 0 ;;
        *)            die "unknown option: $1 (try --help)" ;;
    esac
    shift
done

# Size of a path in KB, 0 if it is gone.
size_kb() {
    [ -e "$1" ] || { echo 0; return; }
    du -sk "$1" 2>/dev/null | awk '{print $1}'
}

human() {
    awk -v kb="$1" 'BEGIN {
        if (kb >= 1048576) printf "%.1f GB", kb / 1048576
        else if (kb >= 1024) printf "%.0f MB", kb / 1024
        else printf "%d KB", kb
    }'
}

# Delete a path, accounting for what it freed. Honours --dry-run.
reap() {
    local path="$1" label="$2" kb
    kb="$(size_kb "$path")"
    [ "$kb" -eq 0 ] && return 0
    RECLAIMED_KB=$((RECLAIMED_KB + kb))
    printf '  %-9s %s  %s\n' "$(human "$kb")" "$label" "${path#"$REPO_ROOT"/}"
    [ "$DRY_RUN" -eq 1 ] || rm -rf -- "$path"
}

# Within target/*/build, group directories by package name and by kind — a
# build-script binary dir and an `out/` payload dir are separate lineages, so
# each keeps its own generations. Keep the $KEEP newest per lineage, reap the
# rest.
prune_build_dirs() {
    local build_dir="$1"
    [ -d "$build_dir" ] || return 0

    local listing
    listing="$(
        for d in "$build_dir"/*/; do
            d="${d%/}"
            [ -d "$d" ] || continue
            local base kind
            base="${d##*/}"
            kind=script
            [ -d "$d/out" ] && kind=out
            # The trailing -<hash> is the only dash-delimited field cargo adds.
            printf '%s%s%s|%s%s%s\n' "$(stat -f %m "$d")" "$TAB" "${base%-*}" "$kind" "$TAB" "$d"
        done | sort -t"$TAB" -k2,2 -k1,1nr
    )"

    [ -n "$listing" ] || return 0

    local stale
    stale="$(printf '%s\n' "$listing" | awk -F"$TAB" -v keep="$KEEP" '++seen[$2] > keep { print $3 }')"
    [ -n "$stale" ] || return 0

    while IFS= read -r d; do
        [ -n "$d" ] && reap "$d" "stale build"
    done <<< "$stale"
}

echo "Cleaning stale build artifacts in $REPO_ROOT"
[ "$DRY_RUN" -eq 1 ] && echo "(dry run — nothing will be deleted)"
echo

echo "Superseded build-script directories (keeping $KEEP newest per package):"
for profile_dir in target/*/; do
    prune_build_dirs "${profile_dir}build"
done

echo
echo "Incremental compilation caches:"
for profile_dir in target/*/; do
    reap "${profile_dir}incremental" "incremental"
done

if [ "$DO_ESP32" -eq 1 ]; then
    echo
    echo "ESP32 firmware build tree (the .embuild toolchain is left alone):"
    reap "satellite-esp32/target" "esp32"
fi

if [ "$DO_SDD" -eq 1 ]; then
    echo
    echo "Finished review scratch older than $SDD_AGE_DAYS days:"
    if [ -d .superpowers/sdd ]; then
        while IFS= read -r f; do
            [ -n "$f" ] && reap "$f" "sdd"
        done < <(find .superpowers/sdd -maxdepth 1 -type f \
                    \( -name 'review-*.diff' -o -name '*-report.md' \) \
                    -mtime +"$SDD_AGE_DAYS" 2>/dev/null | sort)
    fi
fi

# Long-lived athena processes are easy to lose track of: a `serve` launched from
# a throwaway session config reparents to launchd and keeps running for days,
# holding port 8080 and running a binary that no longer matches the source. This
# only reports — deciding what to stop is yours.
echo
echo "Running athena processes:"
procs="$(pgrep -fl 'athena-voice' 2>/dev/null | grep -v clean-stale || true)"
if [ -z "$procs" ]; then
    echo "  none"
else
    while IFS= read -r line; do
        [ -n "$line" ] || continue
        pid="${line%% *}"
        printf '  pid %-7s up %-12s %s\n' \
            "$pid" \
            "$(ps -o etime= -p "$pid" 2>/dev/null | tr -d ' ')" \
            "$(ps -o command= -p "$pid" 2>/dev/null | cut -c1-90)"
        # A config living under /private/tmp disappears when macOS prunes it,
        # so the process survives only until its next restart.
        case "$line" in
            */private/tmp/*) echo "      ^ config is in /private/tmp — will not survive a restart" ;;
        esac
    done <<< "$procs"
fi

echo
if [ "$RECLAIMED_KB" -eq 0 ]; then
    echo "Nothing stale to remove."
else
    verb=$([ "$DRY_RUN" -eq 1 ] && echo "Would reclaim" || echo "Reclaimed")
    printf '%s %s\n' "$verb" "$(human "$RECLAIMED_KB")"
fi

df -h . | awk 'NR==2 {printf "Free on %s: %s of %s\n", $NF, $4, $2}'
